Hypothesis TRP1 : In [0x97418] CLIENT_TRACES.
Hypothesis TRP2 : In [0x97428] CLIENT_TRACES.
Hypothesis TRPD : Forall (fun f => In [f; 0x97370] CLIENT_TRACES) DESTROY_FREE_RAS.

